import{z as s,x as l,o as t,c as p,q as B,j as A,D as e,d as r,s as o,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"美人竞赛与高阶信念","description":"","frontmatter":{"title":"美人竞赛与高阶信念","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/beauty-contest-higher-order.md","filePath":"econ/beauty-contest-higher-order.md","lastUpdated":1791063341000}'),d={name:"econ/beauty-contest-higher-order.md"};function h(m,a,C,c,u,D){const n=l("Mermaid");return t(),p("div",null,[a[2]||(a[2]=B('<h1 id="美人竞赛与高阶信念" tabindex="-1">美人竞赛与高阶信念 <a class="header-anchor" href="#美人竞赛与高阶信念" aria-label="Permalink to &quot;美人竞赛与高阶信念&quot;">​</a></h1><div class="epigraph"><p>职业投资是猜平均意见的平均意见；三阶以上，基本面可以让位给对别人信念的信念。</p><footer>—— 据 Keynes, The General Theory, 1936, 第十二章；Allen, Morris and Shin, Review of Financial Studies, 2006</footer></div><p><a href="/econ/information-acquisition">上一课</a>标明获取可以因协调而互补。本课缺口是把「协调」写成价格里的<strong>高阶信念</strong>：不只是 \\(\\mathrm{E}[\\theta]\\)，还有 \\(\\mathrm{E}[\\mathrm{E}[\\theta\\mid\\cdot]]\\) 以至无穷。不重做买不买信号的博弈型，不把凯恩斯写成行为偏差名录。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>凯恩斯的报纸选美：奖给最接近平均投票的人，理性策略是猜别人怎么猜，不是猜谁最美。资产若短期必须转卖，今天的支付取决于明天的平均估值，明天的平均估值又取决于再后天——价格进入美人竞赛。Allen、Morris 与 Shin（2006）在高斯差分化里把这写成：价格是对 \\(\\theta\\) 的各阶期望的加权和；公共噪声进入每一阶，因而比私有噪声更持久。</p><p><span class="marginnote">「高阶信念」就是关于信念的信念：一阶是「我猜基本面是多少」，二阶是「我猜大家平均猜多少」，三阶是「我猜大家猜大家猜多少」……选美比赛要猜的正是这种层层嵌套的平均意见，而不是谁真的最美。</span></p><p>缺口是：Hellwig–Admati 的 REE 里，人们从价格学习 \\(\\theta\\)，目标仍是对清算值的消费。一旦引入「关心别人的平均预期」（短期定价、相对业绩、流动性外部性），目标函数本身含高阶项。部分揭示不再只是 \\(z\\) 与 \\(\\theta\\) 的混淆，还是高阶公共噪声的放大。</p><p><span class="marginnote">差分化：每人观察公共信号 \\(y\\) 与私有信号 \\(x_i\\)，行动是加权猜测。均衡行动是 \\(y\\) 与 \\(x_i\\) 的线性组合，公共项权重大于贝叶斯权重。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设清算在远期，中间每期价格由平均预期给出（或由短视投资者给出）。迭代期望：</p> \\[p \\propto \\bar{\\mathrm{E}}[\\theta] + \\delta\\,\\bar{\\mathrm{E}}[p&#39;]+\\cdots \\]<p>把 \\(p&#39;\\) 再展开，得到对 \\(\\theta\\) 的一阶、二阶、……期望。高斯下高阶期望仍是 \\((y,x_i)\\) 的线性组合，但 \\(y\\) 的系数随阶数衰减得更慢。于是价格对公共信号过度敏感、对私有信号迟钝——即便每个人的一阶贝叶斯是正确的。</p><p><span class="marginnote">数字实例：100 个人各看一份独立的私有信号，误差有正有负，取平均后误差大约缩小到十分之一；公共信号里那份人人相同的误差，平均一百万次也还是那么大。一层层嵌套猜下去，它一分不少地留在每一阶——这就是「公共噪声更持久」的算术来源。</span></p><p>这与 <a href="/econ/emh">EMH</a> 的半强式不自动冲突：公共 \\(y\\) 已经被写入 \\(p\\)，只是写入的权重相对 \\(\\theta\\) 的最优统计而言太大。有效是相对信息集无经济利润；美人竞赛说的是写入规则的形状。</p>',14)),(t(),A(i,null,{default:e(()=>[o(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20FUND%5B%22%E4%B8%80%E9%98%B6%3A%20E%20%CE%B8%22%5D%20--%3E%20P%5B%22%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20HO%5B%22%E9%AB%98%E9%98%B6%3A%20E%20E%20%CE%B8%22%5D%20--%3E%20P%0A%20%20PUB%5B%22%E5%85%AC%E5%85%B1%E5%99%AA%E5%A3%B0%22%5D%20--%3E%20HO%0A%20%20P%20--%3E%20OVER%5B%22%E5%AF%B9%E5%85%AC%E5%85%B1%E4%BF%A1%E5%8F%B7%E8%BF%87%E5%BA%A6%E6%95%8F%E6%84%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"不要把高阶信念写成限价簿上的「侦测冰山单」。那是协议层的学习；这里没有队列，只有平均意见的平均意见。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是迭代期望的公共项不能被大数定律洗掉。私有误差在加总一阶期望时消失；公共误差在每一阶都还在。短期转卖把未来价格写进今天的支付，等于强迫投资者给高阶项加权。获取互补现在有了精确通道：买公共信号，是因为别人也用它猜别人。",-1)),(t(),A(i,null,{default:e(()=>[o(n,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20I1%5B%22%E7%AC%AC%E4%B8%80%E9%98%B6%EF%BC%9A%E7%A7%81%E6%9C%89%E8%AF%AF%E5%B7%AE%E5%BD%BC%E6%AD%A4%E7%8B%AC%E7%AB%8B%22%5D%20--%3E%20AVG%5B%22%E5%8A%A0%E6%80%BB%E5%B9%B3%E5%9D%87%EF%BC%9A%E7%A7%81%E6%9C%89%E8%AF%AF%E5%B7%AE%E8%A2%AB%E6%B4%97%E6%8E%89%22%5D%0A%20%20I1%20--%3E%20PUB%5B%22%E5%85%AC%E5%85%B1%E8%AF%AF%E5%B7%AE%20y%20%E4%BA%BA%E4%BA%BA%E7%9B%B8%E5%90%8C%22%5D%0A%20%20PUB%20--%3E%20S2%5B%22%E7%AC%AC%E4%BA%8C%E9%98%B6%EF%BC%9A%E7%8C%9C%E5%88%AB%E4%BA%BA%E7%9A%84%E5%B9%B3%E5%9D%87%E7%8C%9C%E6%B5%8B%22%5D%0A%20%20AVG%20--%3E%20S2%0A%20%20S2%20--%3E%20KEEP%5B%22%E5%85%AC%E5%85%B1%E8%AF%AF%E5%B7%AE%E5%8E%9F%E6%A0%B7%E8%BF%9B%E5%85%A5%E7%AC%AC%E4%BA%8C%E9%98%B6%22%5D%0A%20%20KEEP%20--%3E%20K3%5B%22%E7%AC%AC%E4%B8%89%E9%98%B6%E4%BB%A5%E5%90%8E%EF%BC%9A%E4%BB%8D%E4%B8%8D%E6%B6%88%E5%A4%B1%22%5D%0A%20%20K3%20--%3E%20OUT%5B%22%E4%BB%B7%E6%A0%BC%E7%9A%84%E5%85%AC%E5%85%B1%E4%BF%A1%E5%8F%B7%E6%9D%83%E9%87%8D%E8%B6%8A%E6%BB%9A%E8%B6%8A%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>GS 的 \\(z\\) 是供给噪声，进入一阶混淆。美人竞赛的公共噪声即使与供给无关，也会因高阶而活下来。两种残差不要并成一个「噪声交易者」。</p><p><span class="marginnote">Angeletos 与 Werning 把金融价格当作内生公共信号，接到宏观协调博弈。本课只钉资产价格里的高阶，不写货币攻击。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把第十二章读成「市场全是心理」。凯恩斯同时写了长期投资者仍应看基本面；美人竞赛是流动性与短期评价迫使的均衡，不是偏好改写。下一课 Morris–Shin 把过度权重写成福利：公共信息可以有负的社会价值。本课不审央行该不该透明。</p><p><span class="marginnote">常见误区：把美人竞赛读成「市场就是瞎猜心理」。均衡里每个人都在做贝叶斯最优——只是目标里被迫含了「别人怎么猜」这一项；这是短期必须转卖的制度结果，不是投资者不理性。若人人都能持有到期，高阶层会自动塌掉。</span></p><p>后课默认：短期定价引入高阶期望；公共噪声比私有噪声更持久，价格对公共信号的弹性可以超过贝叶斯基准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>美人竞赛把价格写成对平均意见的迭代，而不只是 \\(\\mathrm{E}[\\theta]\\)。</li><li>公共噪声进入每一阶，私有噪声在加总时被洗掉。</li><li>这是协调均衡，不是把上一课的 \\(c\\) 再解一遍。</li><li>出处：Keynes, <em>General Theory</em>, 1936, ch. 12；Allen, Morris and Shin, <em>RFS</em> 2006。</li></ul>',8))])}const F=s(d,[["render",h]]);export{f as __pageData,F as default};
